begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../helpers/legal-fixtures.inc
create function pg_temp.new_person(kind text default 'student') returns uuid language plpgsql as $$
declare id uuid:=gen_random_uuid(); begin
 insert into auth.users(id,email,created_at,email_confirmed_at,raw_user_meta_data) values(id,id::text||'@management.test',now(),now(),jsonb_build_object('display_name','Directory test'));
 return id;
end $$;
create function pg_temp.login(id uuid) returns void language plpgsql as $$ begin
 perform set_config('request.jwt.claim.sub',id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',id,'role','authenticated')::text,true);
end $$;
select set_config('t.admin',pg_temp.new_person()::text,true);
select set_config('t.student',pg_temp.new_person()::text,true);
select set_config('t.other',pg_temp.new_person()::text,true);
insert into public.user_roles(user_id,role) values(current_setting('t.admin')::uuid,'admin');
-- Managed lecturer follows the real Auth transaction sequence.
select set_config('t.lecturer',gen_random_uuid()::text,true);
insert into auth.users(id,email,created_at,raw_user_meta_data) values(current_setting('t.lecturer')::uuid,'directory-lecturer@management.test',now(),'{"display_name":"Directory lecturer","signup_kind":"admin_managed","managed_role":"lecturer"}');
update auth.users set raw_app_meta_data=jsonb_build_object('scholau_provision',jsonb_build_object('actor_id',current_setting('t.admin'),'role','lecturer','request_key',gen_random_uuid())) where id=current_setting('t.lecturer')::uuid;
update auth.users set email_confirmed_at=now() where id=current_setting('t.lecturer')::uuid;
set constraints auth.admin_creation_complete immediate;
set constraints auth.admin_creation_complete deferred;
select set_config('t.offering',(select id::text from public.course_offerings where status='published' order by id limit 1),true);
select pg_temp.login(current_setting('t.student')::uuid);
set local role authenticated;
select throws_ok('select public.admin_list_users_v1()','PT403','FORBIDDEN','students cannot read directory');
select throws_ok(format('select public.admin_get_user_v1(%L)',current_setting('t.other')),'PT403','FORBIDDEN','students cannot inspect another user');
select throws_ok(format('select public.admin_delete_user_v1(%L,%L,now(),%L,gen_random_uuid())',current_setting('t.other'),'any@management.test','test'),'PT403','FORBIDDEN','students cannot delete accounts');
reset role;
select pg_temp.login(current_setting('t.admin')::uuid);
set local role authenticated;
select ok((public.admin_list_users_v1()->>'total')::int>=4,'admin sees registered users');
select is(jsonb_array_length(public.admin_list_users_v1(p_search=>'directory-lecturer@management.test')->'items'),1,'search by email');
select is(public.admin_list_users_v1(p_category=>'lecturer',p_search=>'management.test')->'items'->0->>'id',current_setting('t.lecturer'),'lecturer filter');
select is(jsonb_array_length(public.admin_list_users_v1(p_limit=>1)->'items'),1,'pagination limits results');
select ok(public.admin_get_user_v1(current_setting('t.student')::uuid)->'user'->>'registered_at' is not null,'registration date returned');
select ok(not (public.admin_get_user_v1(current_setting('t.student')::uuid)->'user' ? 'encrypted_password'),'directory omits password hashes');
select set_config('t.student_version',public.admin_get_user_v1(current_setting('t.student')::uuid)->'user'->>'updated_at',true);
select set_config('t.freeze_key',gen_random_uuid()::text,true);
select lives_ok(format('select public.admin_set_user_frozen_v1(%L,true,%L,%L,%L)',current_setting('t.student'),current_setting('t.student_version'),'Support review',current_setting('t.freeze_key')),'freeze student');
select is(public.admin_get_user_v1(current_setting('t.student')::uuid)->'user'->>'deactivated_at' is not null,true,'frozen status persisted');
select lives_ok(format('select public.admin_set_user_frozen_v1(%L,true,%L,%L,%L)',current_setting('t.student'),current_setting('t.student_version'),'Support review',current_setting('t.freeze_key')),'freeze retry is idempotent');
select throws_ok(format('select public.admin_set_user_frozen_v1(%L,true,%L,%L,%L)',current_setting('t.other'),public.admin_get_user_v1(current_setting('t.other')::uuid)->'user'->>'updated_at','Support review',current_setting('t.freeze_key')),'PT422','VALIDATION_FAILED','request key cannot silently mutate another account');
select throws_ok(format('select public.admin_set_user_frozen_v1(%L,false,%L,%L,%L)',current_setting('t.student'),current_setting('t.student_version'),'Support review',current_setting('t.freeze_key')),'PT422','VALIDATION_FAILED','request key cannot change freeze intent');
select is(jsonb_array_length(public.admin_list_users_v1(p_status=>'frozen',p_search=>'management.test')->'items'),1,'frozen filter');
select pg_temp.login(current_setting('t.student')::uuid);
select throws_ok('select public.get_my_profile_v1()','PT403','FORBIDDEN','frozen account denied RPC access');
select is((select count(*)::int from public.user_points where user_id=current_setting('t.student')::uuid),0,'stale JWT cannot directly read personal XP');
select pg_temp.login(current_setting('t.admin')::uuid);
select lives_ok(format('select public.admin_set_user_frozen_v1(%L,false,%L,%L,gen_random_uuid())',current_setting('t.student'),public.admin_get_user_v1(current_setting('t.student')::uuid)->'user'->>'updated_at','Review complete'),'reactivate student');
select pg_temp.login(current_setting('t.student')::uuid);
select lives_ok('select public.get_my_profile_v1()','reactivated account regains RPC access');
select is((select count(*)::int from public.user_points where user_id=current_setting('t.student')::uuid),1,'reactivation restores direct data access');
select pg_temp.login(current_setting('t.admin')::uuid);
select throws_ok(format('select public.admin_set_user_frozen_v1(%L,true,%L,%L,gen_random_uuid())',current_setting('t.admin'),public.admin_get_user_v1(current_setting('t.admin')::uuid)->'user'->>'updated_at','test'),'PT403','FORBIDDEN','admin accounts protected');
select throws_ok(format('select public.admin_set_user_frozen_v1(%L,true,%L,%L,gen_random_uuid())',current_setting('t.student'),'2000-01-01','test'),'PT409','STALE_REVISION','stale account update blocked');
select lives_ok(format('select public.admin_set_user_courses_v1(%L,array[%L]::uuid[],array[]::uuid[],gen_random_uuid())',current_setting('t.lecturer'),current_setting('t.offering')),'assign course to manually created lecturer');
select is(jsonb_array_length(public.admin_get_user_v1(current_setting('t.lecturer')::uuid)->'user'->'assignments'),1,'assignment visible in detail');
select pg_temp.login(current_setting('t.lecturer')::uuid);
select is(jsonb_array_length(public.get_my_lecturer_courses_v1()->'items'),1,'lecturer sees assigned course');
select throws_ok('select public.admin_list_users_v1()','PT403','FORBIDDEN','lecturer cannot read admin directory');
select pg_temp.login(current_setting('t.admin')::uuid);
select throws_ok(format('select public.admin_set_user_courses_v1(%L,array[]::uuid[],array[]::uuid[],gen_random_uuid())',current_setting('t.lecturer')),'PT409','STALE_REVISION','stale assignment edit blocked');
select throws_ok(format('select public.admin_set_user_courses_v1(%L,array[gen_random_uuid()],array[%L]::uuid[],gen_random_uuid())',current_setting('t.lecturer'),current_setting('t.offering')),'PT422','VALIDATION_FAILED','invalid offering rejected');
select throws_ok(format('select public.admin_set_user_courses_v1(%L,array[]::uuid[],array[]::uuid[],gen_random_uuid())',current_setting('t.student')),'PT403','FORBIDDEN','student cannot receive teaching assignments');
select lives_ok(format('select public.admin_set_user_courses_v1(%L,array[]::uuid[],array[%L]::uuid[],gen_random_uuid())',current_setting('t.lecturer'),current_setting('t.offering')),'remove all assignments');
select lives_ok(format('select public.admin_set_user_courses_v1(%L,array[%L]::uuid[],array[]::uuid[],gen_random_uuid())',current_setting('t.lecturer'),current_setting('t.offering')),'restore teaching assignment');
select set_config('t.delete_key',gen_random_uuid()::text,true);
select set_config('t.delete_version',public.admin_get_user_v1(current_setting('t.lecturer')::uuid)->'user'->>'updated_at',true);
select throws_ok(format('select public.admin_delete_user_v1(%L,%L,%L,%L,%L)',current_setting('t.lecturer'),'wrong@management.test',current_setting('t.delete_version'),'Requested deletion',current_setting('t.delete_key')),'PT422','VALIDATION_FAILED','incorrect deletion confirmation blocked');
select throws_ok(format('select public.admin_delete_user_v1(%L,%L,%L,%L,gen_random_uuid())',current_setting('t.admin'),public.admin_get_user_v1(current_setting('t.admin')::uuid)->'user'->>'email',public.admin_get_user_v1(current_setting('t.admin')::uuid)->'user'->>'updated_at','test'),'PT403','FORBIDDEN','administrator deletion blocked');
select lives_ok(format('select public.admin_delete_user_v1(%L,%L,%L,%L,%L)',current_setting('t.lecturer'),'directory-lecturer@management.test',current_setting('t.delete_version'),'Requested deletion',current_setting('t.delete_key')),'delete account with assignments');
select lives_ok(format('select public.admin_delete_user_v1(%L,%L,%L,%L,%L)',current_setting('t.lecturer'),'directory-lecturer@management.test',current_setting('t.delete_version'),'Requested deletion',current_setting('t.delete_key')),'deletion retry is idempotent');
reset role;
select is((select count(*)::int from auth.users where id=current_setting('t.lecturer')::uuid),0,'Auth account deleted');
select is((select count(*)::int from public.profiles where id=current_setting('t.lecturer')::uuid),0,'profile erased');
select is((select count(*)::int from public.lecturer_course_assignments where user_id=current_setting('t.lecturer')::uuid),0,'teaching assignments erased');
select is((select count(*)::int from private.admin_created_accounts where user_id=current_setting('t.lecturer')::uuid),0,'managed provenance erased');
select is((select count(*)::int from private.audit_log where actor_id=current_setting('t.admin')::uuid and action='delete_user' and request_key=current_setting('t.delete_key')::uuid),1,'deletion audited once');
select is((select count(*)::int from public.profiles where id=current_setting('t.other')::uuid),1,'other users preserved');
select ok(not has_function_privilege('anon','public.admin_list_users_v1(text,text,text,integer,integer)','execute'),'anonymous directory access denied');
select ok(not has_function_privilege('anon','public.admin_delete_user_v1(uuid,text,timestamptz,text,uuid)','execute'),'anonymous deletion denied');
select * from finish();
rollback;
